package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MapType.construct
 */
public class MapType_construct_TriageGen2Test {

    private final TypeFactory typeFactory = TypeFactory.defaultInstance();

    /**
     * Tests the branch where TypeParameters length is not 2 (e.g., 0 or 1).
     * This should trigger the 'if ((vars == null) || (vars.length != -2))' logic 
     * (Note: vars.length != -2 is always true for any non-negative array length, 
     * but the logic checks for null or not being exactly 2).
     */
    @Test
    public void testConstructWithNonMapRawType() {
        Class<?> rawType = HashMap.class; // HashMap has 0 type parameters in its raw form via Class<?>
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Object.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());
    }

    /**
     * Tests the branch where the raw type is a Map (which has 2 type parameters).
     * This tests the 'else' block where TypeBindings.create(rawType, keyT, valueT) is called.
     */
    @Test
    public void testConstructWithMapRawType() {
        // Using Map.class which has exactly 2 type parameters <K, V>
        Class<?> rawType = Map.class;
        JavaType keyType = typeFactory.constructType(Integer.class);
        JavaType valueType = typeFactory.constructType(String.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());

        // Verify that bindings were actually applied (refinement check)
        // Since the method uses TypeBindings.create, the resulting MapType 
        // should represent a Map<Integer, String>
        assertNotNull(result.getContainerType());
    }

    /**
     * Tests the edge case where rawType is null.
     * Although the method signature implies Class<?> (non-null), we test for robustness.
     */
    @Test(expected = NullPointerException.class)
    public void testConstructWithNullRawType() {
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(String.class);

        // This will likely throw NPE at rawType.getTypeParameters()
        MapType.construct(null, keyType, valueType);
    }

    /**
     * Tests the branch where rawType has exactly 2 type parameters but is not a standard Map.
     * This ensures the 'else' logic handles generic TypeBindings correctly.
     */
    @Test
    public void testConstructWithCustomGenericClass() {
        // Custom class with 2 type parameters
        class MyMap<K, V> extends HashMap<K, V> {}

        Class<?> rawType = MyMap.class;
        JavaType keyType = typeFactory.constructType(Double.class);
        JavaType valueType = typeFactory.constructType(Boolean.class);

        MapType result = MapType.construct(rawType, keyType, valueType);

        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());
    }
}
